export const SELO_SVGS: Record<string, (...a: unknown[]) => string> = {

  /* --- Triângulo de Möbius ISO 7000-1135 — desenhado com 3 setas
     simétricas (120° de rotação cada). Cada "seta" é um triângulo
     com um corte que forma a flecha. Geometria validada visualmente.
     OBS: Mantido como fallback. Os SVGs oficiais reais são usados via
     MATERIAL_SVGS lookup nas funções pet/pead/etc. --- */
  _mobius: (num, label) => `
    <g fill="currentColor">
      <g transform="translate(50 47)">
        <g>
          <path d="M -16 -22 L 16 -22 L 8 -8 L -8 -8 Z" />
          <path d="M 16 -22 L 22 -14 L 8 -8 Z" />
        </g>
        <g transform="rotate(120)">
          <path d="M -16 -22 L 16 -22 L 8 -8 L -8 -8 Z" />
          <path d="M 16 -22 L 22 -14 L 8 -8 Z" />
        </g>
        <g transform="rotate(240)">
          <path d="M -16 -22 L 16 -22 L 8 -8 L -8 -8 Z" />
          <path d="M 16 -22 L 22 -14 L 8 -8 Z" />
        </g>
      </g>
      <text x="50" y="56" font-family="Archivo,Arial,sans-serif" font-size="22"
        font-weight="800" text-anchor="middle" fill="currentColor">${num}</text>
      ${label ? `<text x="50" y="93" font-family="Archivo,Arial,sans-serif" font-size="14"
        font-weight="800" text-anchor="middle" fill="currentColor" letter-spacing="0.4">${label}</text>` : ''}
    </g>`,

  /* === Materiais — usa SVGs oficiais fornecidos pelo usuário ===
     Lookup em MATERIAL_SVGS por chave. Fallback para _mobius desenhado. */
  pet:    () => MATERIAL_SVGS.pet    ? MATERIAL_SVGS.pet.inner    : SELO_SVGS._mobius(1, 'PET'),
  pead:   () => MATERIAL_SVGS.pead   ? MATERIAL_SVGS.pead.inner   : SELO_SVGS._mobius(2, 'PEAD'),
  pvc:    () => MATERIAL_SVGS.pvc    ? MATERIAL_SVGS.pvc.inner    : SELO_SVGS._mobius(3, 'PVC'),
  pebd:   () => MATERIAL_SVGS.pebd   ? MATERIAL_SVGS.pebd.inner   : SELO_SVGS._mobius(4, 'PEBD'),
  pp:     () => MATERIAL_SVGS.pp     ? MATERIAL_SVGS.pp.inner     : SELO_SVGS._mobius(5, 'PP'),
  ps:     () => MATERIAL_SVGS.ps     ? MATERIAL_SVGS.ps.inner     : SELO_SVGS._mobius(6, 'PS'),
  outros: () => MATERIAL_SVGS.outros ? MATERIAL_SVGS.outros.inner : SELO_SVGS._mobius(7, 'OUTROS'),
  // Materiais não-plásticos
  pap:    () => MATERIAL_SVGS.pap    ? MATERIAL_SVGS.pap.inner    : '',
  alu:    () => MATERIAL_SVGS.alu    ? MATERIAL_SVGS.alu.inner    : '',
  gls:    () => MATERIAL_SVGS.gls    ? MATERIAL_SVGS.gls.inner    : '',

  /* === Selo "RECICLÁVEL" — SVG oficial fornecido (Möbius europeu padrão) === */
  reciclavel: () => RECYCLING_SVGS.reciclavel
    ? RECYCLING_SVGS.reciclavel.inner
    : `<g fill="currentColor"><g transform="translate(50 40)"><path d="M -16 -22 L 16 -22 L 8 -8 L -8 -8 Z"/><path d="M 16 -22 L 22 -14 L 8 -8 Z"/><g transform="rotate(120)"><path d="M -16 -22 L 16 -22 L 8 -8 L -8 -8 Z"/><path d="M 16 -22 L 22 -14 L 8 -8 Z"/></g><g transform="rotate(240)"><path d="M -16 -22 L 16 -22 L 8 -8 L -8 -8 Z"/><path d="M 16 -22 L 22 -14 L 8 -8 Z"/></g></g><text x="50" y="92" font-family="Archivo,Arial,sans-serif" font-size="13" font-weight="800" text-anchor="middle" fill="currentColor" letter-spacing="1">RECICLÁVEL</text></g>`,

  /* === Selo "eureciclo" — SVG oficial fornecido ===
     Logo da plataforma de compensação ambiental Eureciclo. */
  eureciclo: () => RECYCLING_SVGS.eureciclo
    ? RECYCLING_SVGS.eureciclo.inner
    : `<g fill="currentColor"><circle cx="50" cy="44" r="26" fill="none" stroke="currentColor" stroke-width="3.5"/><text x="50" y="50" font-family="Archivo,Arial,sans-serif" font-size="9" font-weight="700" text-anchor="middle" fill="currentColor">EURECICLO</text></g>`,

  /* === Selo "Jogue no Lixo" — SVG oficial fornecido ===
     Selo brasileiro: figura jogando lixo na lixeira de reciclagem. */
  jogueLixo: () => RECYCLING_SVGS.jogueLixo
    ? RECYCLING_SVGS.jogueLixo.inner
    : `<g fill="currentColor"><rect x="32" y="28" width="36" height="48" rx="3" fill="none" stroke="currentColor" stroke-width="3"/><text x="50" y="92" font-family="Archivo,Arial,sans-serif" font-size="8" font-weight="800" text-anchor="middle" fill="currentColor">JOGUE NO LIXO</text></g>`,


  /* === Vegano — SVG oficial fornecido pelo usuário ===
     Logo "VEGAN" com folha estilizada. Inclui texto integrado. */
  vegano: () => ETHICAL_SVGS.vegano
    ? ETHICAL_SVGS.vegano.inner
    : `<g fill="currentColor"><path d="M 50 14 C 32 14, 22 28, 22 44 C 22 58, 32 68, 48 70 C 48 70, 50 56, 50 14 Z M 50 14 C 68 14, 78 28, 78 44 C 78 58, 68 68, 52 70 C 52 70, 50 56, 50 14 Z" /><text x="50" y="92" font-family="Archivo,Arial,sans-serif" font-size="13" font-weight="800" text-anchor="middle" fill="currentColor" letter-spacing="1.5">VEGAN</text></g>`,

  /* === Cruelty Free / Não testado em animais — SVG oficial fornecido ===
     "Não testado em animais" em PT-BR. Inclui texto e ilustração de coelho.
     Tanto crueltyFree quanto naoTestado usam o mesmo SVG (são o mesmo selo). */
  crueltyFree: () => ETHICAL_SVGS.crueltyFree
    ? ETHICAL_SVGS.crueltyFree.inner
    : `<g fill="currentColor"><circle cx="50" cy="50" r="35" fill="none" stroke="currentColor" stroke-width="3"/><text x="50" y="55" font-family="Archivo,Arial,sans-serif" font-size="10" font-weight="800" text-anchor="middle" fill="currentColor">CRUELTY FREE</text></g>`,

  naoTestado: () => ETHICAL_SVGS.crueltyFree
    ? ETHICAL_SVGS.crueltyFree.inner
    : `<g fill="currentColor"><circle cx="50" cy="50" r="35" fill="none" stroke="currentColor" stroke-width="3"/><text x="50" y="55" font-family="Archivo,Arial,sans-serif" font-size="9" font-weight="800" text-anchor="middle" fill="currentColor">NÃO TESTADO</text></g>`,

  /* === PAO (Period After Opening) ISO 15223-1 ===
     Usa SVGs oficiais fornecidos pelo usuário. viewBox 0 0 1000 1000.
     Para meses não cadastrados, faz fallback no 12M com texto sobreposto. */
  _pao: (months) => {
    const svg = PAO_SVGS[months];
    if(svg) return svg;
    // Fallback: usa o 12M como base e sobrepõe o texto
    const base = PAO_SVGS['12M'] || '';
    return base;
  },
};

