['1M','2M','3M','4M','5M','6M','7M','8M','9M','10M','12M','18M','24M','36M','48M'].forEach(m=>{
  SELO_SVGS['pao_'+m] = () => SELO_SVGS._pao(m);
});

/* Retorna o path SVG de uma forma da galeria */
export function getShapeSVG(shapeKind){
  const s = SHAPE_LIB[shapeKind];
  if(!s) return '<rect width="100" height="100" fill="currentColor"/>';
  return `<path d="${s.path}" fill="currentColor"/>`;
}

/* Lista shapes agrupados por categoria */
export function getShapesByCategory(){
  const cats = {};
  Object.entries(SHAPE_LIB).forEach(([key, s])=>{
    if(!cats[s.cat]) cats[s.cat] = [];
    cats[s.cat].push({ key, name:s.name });
  });
  return cats;
}

/* Mapa de "seloKind do estado" → "kind do SVG library" */
export function seloKindToSvg(kind){
  // kind do estado pode ser: 'vegano', 'recic' (materialReciclavel), 'eurec' (euReciclo),
  // 'cf' (crueltyFree), 'nt' (naoTestado), 'mat' (tipoMaterial — com label PET/PEAD/...),
  // 'pao' (validade — com label 12M/24M/...)
  return kind;
}

/* Retorna o SVG string completo de um selo */
export function getSeloSVG(seloKind, color){
  const fn = SELO_SVGS[seloKind];
  if(!fn){
    // fallback: símbolo de placeholder com a label
    return `<g fill="${color||'currentColor'}">
      <rect x="10" y="10" width="80" height="80" rx="8" fill="none" stroke="currentColor" stroke-width="3"/>
      <text x="50" y="58" font-family="Archivo,Arial,sans-serif" font-size="14"
        font-weight="800" text-anchor="middle" fill="currentColor">${seloKind}</text>
    </g>`;
  }
  return fn();
}

